import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import { AuthContext } from '../contexts/AuthContext';

interface User {
  id: number;
  username: string;
  email: string;
  followers_count: number;
  following_count: number;
}

const UserList: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { user: currentUser } = useContext(AuthContext);
  const [followingStatus, setFollowingStatus] = useState<{[key: number]: boolean}>({});

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      setLoading(true);
      // Fetch all users
      const response = await axios.get('/api/posts/');
      
      // Extract unique users from posts
      const postsData = response.data;
      const userIds = new Set(postsData.map((post: any) => post.user));
      
      // Fetch user details for each user ID
      const userPromises = Array.from(userIds).map((userId: any) => 
        axios.get(`/api/profile/${userId}/`)
      );
      
      const userResponses = await Promise.all(userPromises);
      const userData = userResponses.map(response => response.data);
      
      setUsers(userData);
      
      // Check if current user is following each user
      if (currentUser) {
        const followStatusObj: {[key: number]: boolean} = {};
        for (const user of userData) {
          if (user.id !== currentUser.id) {
            try {
              // This is a simplified approach - in a real app, you might want to 
              // fetch the following status in bulk rather than one by one
              const followResponse = await axios.get(`/api/users/${user.id}/follow-status/`);
              followStatusObj[user.id] = followResponse.data.is_following;
            } catch (err) {
              console.error(`Error checking follow status for user ${user.id}:`, err);
              followStatusObj[user.id] = false;
            }
          }
        }
        setFollowingStatus(followStatusObj);
      }
      
      setError(null);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to load users. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  const handleFollowToggle = async (userId: number) => {
    try {
      if (followingStatus[userId]) {
        // Unfollow
        await axios.post(`/api/users/${userId}/unfollow/`);
        setFollowingStatus({
          ...followingStatus,
          [userId]: false
        });
      } else {
        // Follow
        await axios.post(`/api/users/${userId}/follow/`);
        setFollowingStatus({
          ...followingStatus,
          [userId]: true
        });
      }
      
      // Refresh the user list to update follower counts
      fetchUsers();
    } catch (err) {
      console.error('Error toggling follow status:', err);
      setError('Failed to update follow status. Please try again.');
    }
  };

  if (loading) {
    return <div>Loading users...</div>;
  }

  return (
    <div>
      <h2>Users</h2>
      
      {error && <div className="alert alert-danger">{error}</div>}
      
      {users.length === 0 ? (
        <p>No users found.</p>
      ) : (
        <div className="user-list">
          {users.map(user => (
            <div key={user.id} className="card" style={{ marginBottom: '10px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3>{user.username}</h3>
                  <p>Followers: {user.followers_count} | Following: {user.following_count}</p>
                </div>
                {currentUser && user.id !== currentUser.id && (
                  <button 
                    onClick={() => handleFollowToggle(user.id)}
                    className={`btn ${followingStatus[user.id] ? 'btn-secondary' : 'btn-primary'}`}
                  >
                    {followingStatus[user.id] ? 'Unfollow' : 'Follow'}
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default UserList;
